package io.phext.libphext

import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.IOException

/**
 * Port of libphext-rs `src/test_seal.rs` (5 tests). The rs round-trip test
 * seals the crate's `unit-test.phext` corpus file (generated by the fs
 * test in test_lib.rs); here the corpus is the same multi-scroll document
 * that test constructs, inline — content assertions are unchanged.
 */
class SealTest {

    private val corpus =
        "a simple phext doc with three scrolls\u0017we just want to verify\u0017that all of our breaks are making it through rust's fs layer.\u0018section 2\u0019chapter 2\u001Abook 2\u001Cvolume 2\u001Dcollection 2\u001Eseries 2\u001Fshelf 2\u0001library 2"

    @Test
    fun testSealRoundTripRealPhext() {
        val sealed = Seal.seal(corpus)
        assertTrue(sealed.isNotEmpty())
        // an xz stream starts with the xz magic bytes
        assertArrayEquals(
            byteArrayOf(0xFD.toByte(), '7'.code.toByte(), 'z'.code.toByte(), 'X'.code.toByte(), 'Z'.code.toByte(), 0x00),
            sealed.copyOfRange(0, 6),
        )
        val restored = Seal.unsealString(sealed)
        assertEquals(corpus, restored)
    }

    @Test
    fun testSealRoundTripEmptyAndSmall() {
        val sealed = Seal.seal("")
        assertEquals("", Seal.unsealString(sealed))

        val sealed2 = Seal.seal("hello phext")
        assertArrayEquals("hello phext".toByteArray(Charsets.UTF_8), Seal.unseal(sealed2))
    }

    @Test
    fun testSealCarryingBinaryScrolls() {
        // a phext holding base64 binary scrolls (the canonical literal form)
        // seals and unseals with every scroll intact
        val doc = "cover text\u0017phext-binary:1:base64\nAAEC/f7/fw==\u0017after"
        val sealed = Seal.seal(doc)
        val restored = Seal.unsealString(sealed)
        assertEquals(doc, restored)
    }

    @Test
    fun testSealIsDeterministic() {
        val doc = "the same phext, sealed twice\u0017the same phext, sealed twice"
        val first = Seal.seal(doc)
        val second = Seal.seal(doc)
        assertArrayEquals(first, second)
    }

    @Test
    fun testUnsealRejectsNonXzData() {
        assertThrows(IOException::class.java) { Seal.unseal("this is not an xz stream".toByteArray(Charsets.UTF_8)) }
        assertThrows(IOException::class.java) { Seal.unseal(ByteArray(0)) }
        assertThrows(IOException::class.java) { Seal.unsealString("phext, but unsealed".toByteArray(Charsets.UTF_8)) }
    }
}
